mapper.select:
SELECT r.RECEIPT_ID, r.RECEIPT_NO, r.CUSTOMER_ID, r.RECEIPT_AMOUNT, r.WRITE_OFF_AMOUNT, r.REMAINING_AMOUNT, r.RECEIPT_STATUS, r.RECEIPT_DATE, r.PAYMENT_METHOD, r.BANK_NAME, r.BANK_ACCOUNT, r.CONFIRM_AMOUNT, r.CONFIRM_DATE, r.CONFIRM_BY, r.CANCEL_REASON, r.CANCEL_TIME, r.CANCEL_BY, r.REMARKS, r.TENANT_ID, r.ORG_ID, r.CREATE_TIME, r.CREATE_BY, r.UPDATE_TIME, r.UPDATE_BY, r.IS_DELETED, c.CUSTOMER_NAME AS customerName FROM TBL_AR_RECEIPT r LEFT JOIN TBL_AR_CUSTOMER c ON r.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0 WHERE r.IS_DELETED = 0
AND r.TENANT_ID = #{param.tenantId}
AND r.RECEIPT_NO LIKE '%' || #{param.receiptNo} || '%'
AND r.CUSTOMER_ID = #{param.customerId}
AND r.RECEIPT_STATUS = #{param.receiptStatus}
ORDER BY r.CREATE_TIME DESC
